"use client";

import { useDialogFocus } from "@/hooks/useDialogFocus";
import React, { useEffect, useRef, useState } from "react";
import { ArrowDown, ArrowUp, X } from "lucide-react";

const baseCard =
  "admin-card min-w-0 rounded-2xl bg-white";

export function AdminCard({ children, className = "" }: { children: React.ReactNode; className?: string }) {
  return <div className={`${baseCard} ${className}`}>{children}</div>;
}

export function StatusTag({ label, tone = "neutral" }: { label: string; tone?: "neutral" | "green" | "red" | "yellow" | "blue" | "purple" }) {
  const styles: Record<string, string> = {
    neutral: "bg-[var(--bg-secondary)] text-[var(--text-muted)]",
    green: "bg-[#ECFDF3] text-[#28613c]",
    red: "bg-[#FEF2F2] text-[#a33232]",
    yellow: "bg-[#FFFBEB] text-[#87591c]",
    blue: "bg-[#eaf2f8] text-[#376987]",
    purple: "bg-[#F5F3FF] text-[#69528b]",
  };

  return <span className={`inline-flex items-center px-2 py-0.5 text-xs font-semibold rounded-full ${styles[tone]}`}>{label}</span>;
}

export function SortHeader({
  label,
  active,
  direction,
  onClick,
}: {
  label: string;
  active: boolean;
  direction: "asc" | "desc";
  onClick: () => void;
}) {
  return (
    <button onClick={onClick} className="inline-flex items-center gap-1 font-semibold text-left text-[var(--ink)] hover:text-[var(--accent)]">
      <span>{label}</span>
      {active && (direction === "asc" ? <ArrowUp className="w-3.5 h-3.5" /> : <ArrowDown className="w-3.5 h-3.5" />)}
    </button>
  );
}

export function EmptyState({ title, subtitle }: { title: string; subtitle: string }) {
  return (
    <div className="flex flex-col items-center justify-center py-14 text-center text-[var(--text-muted)]">
      <svg width="84" height="84" viewBox="0 0 84 84" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden>
        <rect x="6" y="12" width="72" height="60" rx="12" fill="#f1f6f8" stroke="#d8e2e6" />
        <rect x="18" y="28" width="48" height="8" rx="4" fill="#c7d9e1" />
        <rect x="18" y="42" width="36" height="8" rx="4" fill="#c7d9e1" />
      </svg>
      <p className="mt-4 text-sm font-semibold text-[var(--text-secondary)]">{title}</p>
      <p className="text-sm mt-1">{subtitle}</p>
    </div>
  );
}

export function SkeletonRows({ rows = 6 }: { rows?: number }) {
  return (
    <div className="space-y-2 p-4">
      {Array.from({ length: rows }).map((_, i) => (
        <div key={i} className="h-10 rounded-lg bg-[var(--bg-secondary)] animate-pulse" />
      ))}
    </div>
  );
}

export function ConfirmModal({
  open,
  title,
  description,
  confirmLabel,
  confirmTone,
  onConfirm,
  onClose,
}: {
  open: boolean;
  title: string;
  description: string;
  confirmLabel: string;
  confirmTone: "danger" | "approve";
  onConfirm: () => void | Promise<void>;
  onClose: () => void;
}) {
  const dialogRef = useRef<HTMLDivElement>(null);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState("");
  useDialogFocus(open, dialogRef);
  const close = () => { if (!pending) { setError(""); onClose(); } };
  useEffect(() => {
    if (!open) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [open, onClose]);

  if (!open) return null;

  return (
    <div className="fixed inset-0 z-[80] flex items-center justify-center px-4" onClick={close}>
      <div className="absolute inset-0 bg-black/35" />
      <div ref={dialogRef} role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} className="relative max-h-[calc(100dvh-2rem)] overflow-y-auto w-full max-w-md rounded-xl bg-white border-[3px] border-[var(--border)] shadow-[var(--surface-shadow)] p-5" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-start justify-between gap-3">
          <h3 className="text-lg font-semibold text-[var(--ink)]">{title}</h3>
          <button aria-label="Close dialog" onClick={close} className="p-1 rounded hover:bg-[var(--bg-secondary)]">
            <X className="w-4 h-4 text-[var(--text-muted)]" />
          </button>
        </div>
        <p className="text-sm text-[var(--text-muted)] mt-2">{description}</p>{error && <p role="alert" className="text-red-700 mt-2">{error}</p>}
        <div className="mt-5 flex flex-wrap items-center justify-end gap-2">
          <button onClick={close} className="px-3 py-2 text-sm rounded-lg border-[3px] border-[var(--border)] text-[var(--text-muted)] hover:bg-[var(--bg-primary)]">Cancel</button>
          <button
            disabled={pending}
            onClick={async () => { setPending(true); setError(""); try { await onConfirm(); } catch (error) { setError((error as Error).message || "Could not save changes."); } finally { setPending(false); } }}
            className={`px-3 py-2 text-sm rounded-lg text-white font-semibold ${confirmTone === "danger" ? "bg-[#DC2626] hover:bg-[#B91C1C]" : "bg-[#16A34A] hover:bg-[#15803D]"}`}
          >
            {pending ? "Working…" : confirmLabel}
          </button>
        </div>
      </div>
    </div>
  );
}

export function SideDrawer({
  open,
  title,
  onClose,
  children,
}: {
  open: boolean;
  title: string;
  onClose: () => void;
  children: React.ReactNode;
}) {
  const drawerRef = useRef<HTMLElement>(null);
  useDialogFocus(open, drawerRef);
  useEffect(() => {
    if (!open) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [open, onClose]);

  return (
    <>
      <div
        className={`fixed inset-0 z-[70] bg-black/25 transition-opacity ${open ? "opacity-100 pointer-events-auto" : "opacity-0 pointer-events-none"}`}
        onClick={onClose}
      />
      <aside ref={drawerRef} role="dialog" aria-modal={open || undefined} aria-label={title} tabIndex={-1} inert={!open}
        className={`fixed top-0 right-0 z-[75] h-dvh w-full sm:w-[540px] sm:max-w-[92vw] bg-white border-l border-[var(--border)] shadow-[var(--surface-shadow)] transition-transform ${open ? "translate-x-0" : "translate-x-full"}`}
      >
        <div className="h-full flex flex-col">
          <div className="p-4 border-b border-[var(--border)] flex items-center justify-between">
            <h3 className="font-semibold text-[var(--ink)]">{title}</h3>
            <button aria-label="Close dialog" onClick={onClose} className="p-1 rounded hover:bg-[var(--bg-secondary)]"><X className="w-4 h-4 text-[var(--text-muted)]" /></button>
          </div>
          <div className="min-h-0 p-4 pb-[max(16px,env(safe-area-inset-bottom))] overflow-y-auto overscroll-contain flex-1">{children}</div>
        </div>
      </aside>
    </>
  );
}

export const tableCell = "px-3 py-2 text-sm text-[var(--text-secondary)]";
export const tableHead = "px-3 py-2 text-xs font-medium text-[var(--text-muted)] border-b border-[var(--border)] text-left";
